sketch:
// genex.toml: [animation] enabled = true and [physics] enabled = true
// assets/kits/fps-arms.glb: the kit, copied from docs/examples/fps-arms/; fps_arms.py makes it
// src/facets/viewmodel.rs, wired after the rifle's rules (docs/examples/fps-arms/src/facets/):
use genex::animation::{Motion, TriggerParam};
use genex::prelude::*;

const KIT: &str = "kits/fps-arms.glb";

#[derive(Default)]
pub struct ViewModel { kit: Option<(Animator, TriggerParam)> }

pub fn wire(game: &mut Game<super::World>) {
    game.facet_state::<ViewModel>();
    game.on_reset(|sim, _, _, gfx| {
        let Ok(arms) = gfx.character(KIT) else { return };
        let (Some(idle), Some(fire), Some(reload)) = (arms.clip("Idle"), arms.clip("Fire"), arms.clip("Reload")) else { return };
        let mut g = arms.graph();
        let shot = g.trigger("fire");
        let base = g.layer("base");
        g.state(base, "idle", Motion::clip(idle));
        let _reload = g.state(base, "reload", Motion::clip(reload).once()); // + walk, sprint, sights, inspect
        // Shots add to whatever the base plays: Fire's first frame is the hip pose it adds against.
        let shots = g.layer("shots");
        g.layer_additive(shots, fire);
        let none = g.state(shots, "none", Motion::Empty);
        let firing = g.state(shots, "fire", Motion::clip(fire).once());
        g.transition(none, firing).when(shot.fired()).crossfade(0.0);
        g.transition(firing, none).at_end().crossfade(0.03);
        let Ok(graph) = g.build() else { return };
        sim.facets.get_mut::<ViewModel>().kit = arms.animator(&graph).ok().map(|animator| (animator, shot));
    });
    game.on_update(|sim, ctx| {
        let fired = sim.world.fired_at == Some(sim.world.tick); // the rifle's rules ran first
        let Some((animator, shot)) = sim.facets.get_mut::<ViewModel>().kit.as_mut() else { return };
        if fired { animator.fire(*shot); }
        animator.update(ctx.dt);
    });
    game.on_draw(|sim, frame, camera| {
        let Some((animator, _)) = &sim.facets.get::<ViewModel>().kit else { return };
        // The kit is in the camera's frame: draw it at the camera, moved only by sim state.
        let at = Transform::from_translation(camera.position).with_rotation(view_turn(sim.world.yaw, sim.world.pitch));
        frame.tag("hands").id(0x4b49_5441).character(animator, at).end_id();
    });
}

/// The view's turn for a yaw about +y (0 along +x) and a pitch (up positive): the kit looks down -z.
fn view_turn(yaw: f32, pitch: f32) -> Quat {
    Quat::from_rotation_y(-yaw - std::f32::consts::FRAC_PI_2) * Quat::from_rotation_x(pitch)
}
